import json
from fractions import Fraction
from math import isqrt

b, c, area = 68, 60, 960
h = Fraction(2 * area, c)            # height onto side 60
d2 = b * b - h * h                   # squared projection of the 68 side onto the 60 base
d = isqrt(int(d2))
assert d * d == d2

# apex at horizontal offset +/-d from the endpoint where the 68 side meets the base
cands = set()
for x in (d, -d):
    a2 = (c - x) ** 2 + h * h
    a = isqrt(int(a2))
    if a * a == a2:
        cands.add(a)

def heron16(a, b, c):
    return (a + b + c) * (-a + b + c) * (a - b + c) * (a + b - c)

valid = sorted(a for a in cands
               if a > 0 and a + b > c and a + c > b and b + c > a
               and heron16(a, b, c) == 16 * area * area)

if valid:
    print(json.dumps({
        "final_answer": " or ".join(str(v) for v in valid) + " cm",
        "evidence": {"height": str(h), "projection": d, "valid_sides": valid}
    }))
else:
    print("UNSUPPORTED")
